277	    }
278	
279	    order.cancel();
280	    Order savedOrder = orderRepository.save(order);
281	    createNotification(order.getCustomerCpf(), Notification.Type.ORDER_CANCELLED, orderId);
282	
283	    return convertToResponse(savedOrder);
284	  }
