219	import com.fasterxml.jackson.databind.JsonNode;
220	import com.fasterxml.jackson.databind.ObjectMapper;
221	import java.math.BigDecimal;
222	import java.net.URI;
223	import java.net.http.HttpClient;
224	import java.net.http.HttpRequest;
225	import java.net.http.HttpResponse;
226	import java.time.Duration;
227	import org.springframework.beans.factory.annotation.Value;
228	import org.springframework.stereotype.Service;
229	
230	@Service
231	public class TransLogClient {
232	  private final String translogUrl;
233	  private final HttpClient httpClient;
234	  private final ObjectMapper objectMapper;
235	
236	  public TransLogClient(
237	    @Value("${translog.url:}") String translogUrl,
238	    ObjectMapper objectMapper
239	  ) {
240	    this.translogUrl = translogUrl;
241	    this.objectMapper = objectMapper;
242	    this.httpClient = HttpClient.newBuilder()
243	      .connectTimeout(Duration.ofSeconds(2))
244	      .build();
245	  }
246	
247	  public record QuoteResponse(BigDecimal price, int etaDays) {}
248	
249	  public QuoteResponse quote(String zipCode, int weightGrams, String service) throws Exception {
250	    if (translogUrl == null || translogUrl.isEmpty()) {
251	      throw new TransLogUnavailableException();
252	    }
253	
254	    String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
255	      translogUrl, zipCode, weightGrams, service);
256	
257	    HttpRequest request = HttpRequest.newBuilder()
258	      .uri(URI.create(url))
259	      .GET()
260	      .timeout(Duration.ofSeconds(2))
261	      .build();
262	
263	    try {
264	      HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
265	
266	      if (response.statusCode() != 200) {
267	        throw new TransLogUnavailableException();
268	      }
269	
270	      JsonNode json = objectMapper.readTree(response.body());
271	
272	      if (json.has("error")) {
273	        throw new ZipCodeNotServedException();
274	      }
275	
276	      if (!json.has("price_cents") || !json.has("eta_hours")) {
277	        throw new TransLogUnavailableException();
278	      }
279	
280	      long priceCents = json.get("price_cents").asLong();
281	      int etaHours = json.get("eta_hours").asInt();
282	
283	      BigDecimal priceReais = BigDecimal.valueOf(priceCents).divide(
284	        new BigDecimal("100"),
285	        2,
286	        java.math.RoundingMode.HALF_EVEN
287	      );
288	
289	      int etaDays = (int) Math.ceil(etaHours / 24.0);
290	
291	      return new QuoteResponse(priceReais, etaDays);
292	    } catch (java.net.http.HttpTimeoutException | java.net.ConnectException e) {
293	      throw new TransLogUnavailableException();
294	    }
295	  }
296	
297	  public static class TransLogUnavailableException extends Exception {}
298	  public static class ZipCodeNotServedException extends Exception {}
299	}
