318	
319	public enum Coupon {
320	  WELCOME10 {
321	    @Override
322	    public Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx) {
323	      if (!ctx.isFirstPurchase) return Optional.empty();
324	      return Optional.of(productsSubtotal.multiply(new BigDecimal("0.10")));
325	    }
326	  },
327	  MINUS50 {
328	    @Override
329	    public Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx) {
330	      if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) return Optional.empty();
331	      return Optional.of(new BigDecimal("50.00"));
332	    }
333	  },
334	  FREESHIPPING {
335	    @Override
336	    public Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx) {
337	      if (ctx.shippingMethod == ShippingMethod.STORE_PICKUP) return Optional.empty();
338	      return Optional.of(ctx.shippingCost);
339	    }
340	  },
341	  BUY3PAY2 {
342	    @Override
343	    public Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx) {
344	      BigDecimal discount = BigDecimal.ZERO;
345	      for (OrderItem item : ctx.items) {
346	        int freeItems = item.quantity() / 3;
347	        discount = discount.add(
348	          new BigDecimal(freeItems).multiply(
349	            item.price()
350	          )
351	        );
352	      }
353	      return Optional.of(discount);
354	    }
355	  };
356	
357	  public abstract Optional<BigDecimal> calculateDiscount(BigDecimal productsSubtotal, OrderContext ctx);
358	
359	  public static Optional<Coupon> fromCode(String code) {
360	    if (code == null || code.isEmpty()) return Optional.empty();
361	    try {
362	      return Optional.of(Coupon.valueOf(code));
363	    } catch (IllegalArgumentException e) {
364	      return Optional.empty();
365	    }
366	  }
