417	
418	public enum ClubTier {
419	  BRONZE,
420	  SILVER,
421	  GOLD;
422	
423	  public double getCreditPercentage() {
424	    return switch (this) {
425	      case BRONZE -> 0.0;
426	      case SILVER -> 0.02;
427	      case GOLD -> 0.05;
428	    };
