394	import com.loja.order.dto.NotificationResponse;
395	import com.loja.order.model.Notification;
396	import com.loja.order.repository.NotificationRepository;
397	import jakarta.transaction.Transactional;
398	import org.springframework.stereotype.Service;
399	import java.util.List;
400	
401	@Service
402	public class NotificationService {
403	  private final NotificationRepository notificationRepository;
404	
405	  public NotificationService(NotificationRepository notificationRepository) {
406	    this.notificationRepository = notificationRepository;
407	  }
408	
409	  public List<NotificationResponse> getNotifications(String cpf) throws NotFoundException {
410	    List<Notification> notifications = notificationRepository.findByCustomerCpf(cpf);
411	    if (notifications.isEmpty()) {
412	      throw new NotFoundException("CUSTOMER_NOT_FOUND");
413	    }
414	    return notifications.stream()
415	      .map(this::convertToResponse)
416	      .toList();
417	  }
418	
419	  @Transactional
420	  public NotificationResponse markAsRead(Long notificationId) throws NotFoundException {
421	    Notification notification = notificationRepository.findById(notificationId)
422	      .orElseThrow(() -> new NotFoundException("NOTIFICATION_NOT_FOUND"));
423	
424	    notification.markAsRead();
425	    Notification saved = notificationRepository.save(notification);
426	    return convertToResponse(saved);
427	  }
428	
429	  private NotificationResponse convertToResponse(Notification notification) {
430	    return new NotificationResponse(
431	      notification.getId(),
432	      notification.getType().name(),
433	      notification.getOrderId(),
434	      notification.getStatus().name()
435	    );
436	  }
437	
438	  public static class NotFoundException extends Exception {
439	    public NotFoundException(String message) {
440	      super(message);
441	    }
442	  }
443	}
