import com.sun.net.httpserver.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

public class Stub {
  // key = zip|service  or zip|*  ; value = status;delayMs;body
  static Map<String,String[]> cfg = new ConcurrentHashMap<>();
  static Map<String,String> parse(String q){ Map<String,String> m=new HashMap<>(); if(q==null)return m;
    for(String p:q.split("&")){String[] kv=p.split("=",2); m.put(URLDecoder.decode(kv[0],StandardCharsets.UTF_8), kv.length>1?URLDecoder.decode(kv[1],StandardCharsets.UTF_8):"");} return m;}
  static void send(HttpExchange ex,int st,String body) throws IOException{ byte[] b=body.getBytes(StandardCharsets.UTF_8); ex.getResponseHeaders().add("Content-Type","application/json"); ex.sendResponseHeaders(st,b.length); ex.getResponseBody().write(b); ex.close();}
  public static void main(String[] a) throws Exception {
    HttpServer s = HttpServer.create(new InetSocketAddress(Integer.parseInt(a[0])),0);
    s.setExecutor(Executors.newCachedThreadPool());
    PrintWriter log = new PrintWriter(new FileWriter("/tmp/run/stub.log",true),true);
    s.createContext("/set", ex -> { Map<String,String> m=parse(ex.getRequestURI().getRawQuery());
      cfg.put(m.get("zip")+"|"+m.getOrDefault("service","*"), new String[]{m.getOrDefault("status","200"), m.getOrDefault("delay","0"), m.getOrDefault("body","")});
      send(ex,200,"ok"); });
    s.createContext("/v2/quote", ex -> { Map<String,String> m=parse(ex.getRequestURI().getRawQuery());
      log.println(ex.getRequestURI());
      String[] c = cfg.getOrDefault(m.get("zip")+"|"+m.get("service"), cfg.get(m.get("zip")+"|*"));
      if(c==null) c=new String[]{"200","0","{\"price_cents\":3310,\"eta_hours\":41}"};
      try{Thread.sleep(Long.parseLong(c[1]));}catch(Exception e){}
      send(ex,Integer.parseInt(c[0]),c[2]); });
    s.start();
    System.out.println("stub up "+a[0]);
  }
}
EOF
