  try (Connection c = DriverManager.getConnection(System.getenv("DB_URL"), System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
       ResultSet r = c.createStatement().executeQuery(a[0])) {
    int n=r.getMetaData().getColumnCount(); int rows=0;
    while (r.next()) { rows++; StringBuilder sb=new StringBuilder(); for(int i=1;i<=n;i++) sb.append(r.getString(i)).append(" | "); System.out.println(sb);} System.out.println("("+rows+" linhas)");
  }}}
EOF
java -cp $PG Q.java "select table_name from information_schema.tables where table_schema='public'"

